TriggerOraclev10g.body:
DECLARE
  v_anteriores CLOB;
  v_nuevos     CLOB;
BEGIN
  IF UPDATING OR DELETING THEN
    SELECT JSON_OBJECT('ID_LIBRO' VALUE :OLD.ID_LIBRO, 'ISBN' VALUE :OLD.ISBN, 'TITULO' VALUE :OLD.TITULO, 'ANIO_PUBLICACION' VALUE :OLD.ANIO_PUBLICACION, 'EDICION' VALUE :OLD.EDICION, 'IDIOMA' VALUE :OLD.IDIOMA, 'NUM_PAGINAS' VALUE :OLD.NUM_PAGINAS, 'ID_EDITORIAL' VALUE :OLD.ID_EDITORIAL, 'ID_CATEGORIA' VALUE :OLD.ID_CATEGORIA, 'ESTADO' VALUE :OLD.ESTADO) INTO v_anteriores FROM dual;
  END IF;
  IF INSERTING OR UPDATING THEN
    SELECT JSON_OBJECT('ID_LIBRO' VALUE :NEW.ID_LIBRO, 'ISBN' VALUE :NEW.ISBN, 'TITULO' VALUE :NEW.TITULO, 'ANIO_PUBLICACION' VALUE :NEW.ANIO_PUBLICACION, 'EDICION' VALUE :NEW.EDICION, 'IDIOMA' VALUE :NEW.IDIOMA, 'NUM_PAGINAS' VALUE :NEW.NUM_PAGINAS, 'ID_EDITORIAL' VALUE :NEW.ID_EDITORIAL, 'ID_CATEGORIA' VALUE :NEW.ID_CATEGORIA, 'ESTADO' VALUE :NEW.ESTADO) INTO v_nuevos FROM dual;
  END IF;
  SP_REGISTRAR_BITACORA(
    'LIBRO',
    CASE WHEN INSERTING THEN 'INSERT' WHEN UPDATING THEN 'UPDATE' ELSE 'DELETE' END,
    NVL(:NEW.ID_LIBRO, :OLD.ID_LIBRO),
    v_anteriores,
    v_nuevos
  );
END;
